import json
from pathlib import Path


def load_records(path: Path) -> list[dict]:
    """Load a JSONL file, skip blank lines, and raise ValueError with line numbers for invalid JSON."""
    if not path.is_file():
        raise FileNotFoundError(f"No such file: '{path}'")

    records: list[dict] = []
    errors: list[str] = []

    with path.open("r", encoding="utf-8") as fh:
        for lineno, raw_line in enumerate(fh, start=1):
            line = raw_line.strip()
            if not line:
                continue
            try:
                records.append(json.loads(line))
            except json.JSONDecodeError as exc:
                errors.append(f"line {lineno}: {exc.msg} (char {exc.pos})")

    if errors:
        raise ValueError("Invalid JSONL entries:\n"
